//! Pre-launcher puzzle hashes, coins and spends generated by Cloud Wallet's secure the mint implementation, which
//! created the NFT bulk mints already on chain.
//!
//! The eve NFT's p2 puzzle ignores its solution, so only the eve spend's puzzle reveal is compared. The NFT it
//! creates is compared through the expected coins.

use anyhow::Result;
use chia_protocol::{Bytes32, Coin};
use chia_puzzle_types::nft::NftMetadata;
use chia_puzzles::NFT_METADATA_UPDATER_DEFAULT_HASH;
use chia_sdk_driver::{BagAsset, BagFormat, SecureTheBag, SecuredMint, SpendContext};
use chia_sha2::Sha256;
use serde::Deserialize;

#[derive(Deserialize)]
struct Fixtures {
    mints: Vec<MintFixture>,
    bags: Vec<BagFixture>,
}

#[derive(Deserialize)]
struct MintFixture {
    name: String,
    metadata: MetadataFixture,
    royalty_puzzle_hash: String,
    royalty_basis_points: u16,
    p2_puzzle_hash: String,
    pre_launcher_parent_id: String,
    expected: Expected,
}

#[derive(Deserialize)]
struct MetadataFixture {
    edition_number: u64,
    edition_total: u64,
    data_uris: Vec<String>,
    data_hash: Option<String>,
    metadata_uris: Vec<String>,
    metadata_hash: Option<String>,
    license_uris: Vec<String>,
    license_hash: Option<String>,
}

#[derive(Deserialize)]
struct Expected {
    pre_launcher_puzzle_hash: String,
    eve_p2_puzzle_hash: String,
    pre_launcher: CoinFixture,
    launcher: CoinFixture,
    eve_nft: CoinFixture,
    nft: CoinFixture,
    launcher_id: String,
    spends: Vec<SpendFixture>,
}

#[derive(Deserialize)]
struct CoinFixture {
    parent_coin_info: String,
    puzzle_hash: String,
    amount: String,
    coin_id: String,
}

#[derive(Deserialize)]
struct SpendFixture {
    coin_id: String,
    puzzle_reveal: String,
    solution: String,
}

#[derive(Deserialize)]
struct BagFixture {
    leaf_width: Option<usize>,
    root_hash: String,
}

fn bytes32(value: &str) -> Result<Bytes32> {
    Ok(Bytes32::new(hex::decode(value)?.try_into().map_err(
        |_| anyhow::anyhow!("expected 32 bytes: {value}"),
    )?))
}

fn sha256(data: &[u8]) -> String {
    let mut hasher = Sha256::new();
    hasher.update(data);
    hex::encode(hasher.finalize())
}

fn assert_coin(coin: Coin, expected: &CoinFixture, label: &str) {
    assert_eq!(
        hex::encode(coin.parent_coin_info),
        expected.parent_coin_info,
        "{label}: parent"
    );
    assert_eq!(
        hex::encode(coin.puzzle_hash),
        expected.puzzle_hash,
        "{label}: puzzle hash"
    );
    assert_eq!(coin.amount.to_string(), expected.amount, "{label}: amount");
    assert_eq!(
        hex::encode(coin.coin_id()),
        expected.coin_id,
        "{label}: coin id"
    );
}

impl MintFixture {
    fn secured_mint(&self, ctx: &mut SpendContext) -> Result<SecuredMint> {
        let optional = |value: &Option<String>| value.as_deref().map(bytes32).transpose();

        let metadata = ctx.alloc_hashed(&NftMetadata {
            edition_number: self.metadata.edition_number,
            edition_total: self.metadata.edition_total,
            data_uris: self.metadata.data_uris.clone(),
            data_hash: optional(&self.metadata.data_hash)?,
            metadata_uris: self.metadata.metadata_uris.clone(),
            metadata_hash: optional(&self.metadata.metadata_hash)?,
            license_uris: self.metadata.license_uris.clone(),
            license_hash: optional(&self.metadata.license_hash)?,
        })?;

        Ok(SecuredMint::new(
            metadata,
            NFT_METADATA_UPDATER_DEFAULT_HASH.into(),
            bytes32(&self.royalty_puzzle_hash)?,
            self.royalty_basis_points,
            bytes32(&self.p2_puzzle_hash)?,
        ))
    }
}

fn fixtures() -> Result<Fixtures> {
    Ok(serde_json::from_str(include_str!(
        "data/secure_the_mint.json"
    ))?)
}

#[test]
fn secure_the_mint_golden_vectors() -> Result<()> {
    for fixture in fixtures()?.mints {
        let name = &fixture.name;
        let expected = &fixture.expected;

        let mut ctx = SpendContext::new();
        let mint = fixture.secured_mint(&mut ctx)?;

        assert_eq!(
            hex::encode(mint.pre_launcher_puzzle_hash()),
            expected.pre_launcher_puzzle_hash,
            "{name}: pre-launcher puzzle hash"
        );
        assert_eq!(
            hex::encode(mint.eve_p2_puzzle_hash()),
            expected.eve_p2_puzzle_hash,
            "{name}: eve p2 puzzle hash"
        );

        let pre_launcher = Coin::new(
            bytes32(&fixture.pre_launcher_parent_id)?,
            mint.pre_launcher_puzzle_hash(),
            1,
        );
        let output = mint.output(pre_launcher);

        assert_coin(output.pre_launcher, &expected.pre_launcher, name);
        assert_coin(output.launcher, &expected.launcher, name);
        assert_coin(output.eve_nft.coin, &expected.eve_nft, name);
        assert_coin(output.nft.coin, &expected.nft, name);
        assert_eq!(
            hex::encode(output.nft.info.launcher_id),
            expected.launcher_id,
            "{name}: launcher id"
        );

        assert_eq!(mint.mint(&mut ctx, pre_launcher)?, output, "{name}: output");

        let coin_spends = ctx.take();
        assert_eq!(coin_spends.len(), expected.spends.len(), "{name}: spends");

        for (index, (coin_spend, expected)) in coin_spends.iter().zip(&expected.spends).enumerate()
        {
            assert_eq!(
                hex::encode(coin_spend.coin.coin_id()),
                expected.coin_id,
                "{name}: spend {index} coin"
            );
            assert_eq!(
                sha256(&coin_spend.puzzle_reveal),
                expected.puzzle_reveal,
                "{name}: spend {index} puzzle reveal"
            );

            // The eve spend is last, and its p2 solution is ignored by the puzzle
            if index < 2 {
                assert_eq!(
                    sha256(&coin_spend.solution),
                    expected.solution,
                    "{name}: spend {index} solution"
                );
            }
        }
    }

    Ok(())
}

#[test]
fn secure_the_mint_bag_golden_vectors() -> Result<()> {
    let fixtures = fixtures()?;
    let mut ctx = SpendContext::new();

    let payments = fixtures
        .mints
        .iter()
        .map(|fixture| Ok(fixture.secured_mint(&mut ctx)?.bag_payment()))
        .collect::<Result<Vec<_>>>()?;

    for bag in fixtures.bags {
        let format = BagFormat::Legacy {
            leaf_width: bag.leaf_width,
            sorted: false,
        };
        let built = SecureTheBag::build(format, BagAsset::Xch, payments.clone())?;
        assert_eq!(
            hex::encode(built.root_hash()),
            bag.root_hash,
            "leaf width {:?}",
            bag.leaf_width
        );
    }

    Ok(())
}
